import{_ as n,l as i,o as e,c as s,v as t,p as l,x as o,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"定点与浮点","description":"","frontmatter":{"title":"定点与浮点","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fixed-and-float.md","filePath":"cs/fixed-and-float.md","lastUpdated":1789023840000}'),h={name:"cs/fixed-and-float.md"};function c(m,a,f,_,A,u){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="定点与浮点" tabindex="-1">定点与浮点 <a class="header-anchor" href="#定点与浮点" aria-label="Permalink to &quot;定点与浮点&quot;">​</a></h1><div class="epigraph"><p>整数编码把小数点钉死在某一位；要同时覆盖很大和很小，必须让小数点跟着指数走。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Goldberg, What Every Computer Scientist Should Know About Floating-Point Arithmetic, 1991 整理</footer></div><p>上一课<a href="/cs/sign-magnitude">符号幅度与反码对照</a>钉死了有符号整数：同一套模 \\(2^n\\) 加法，溢出按同号和异号读。本课不重讲负权，也不从「实数是什么」另起。缺口是：补码只能表示整数。测量、比例、后课的地址偏移以外的「带小数的量」，还没有编码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 位补码的间距处处是 \\(1\\)。要把间距改成 \\(2^{-f}\\)，只需宣布小数点在第 \\(f\\) 位之后：这是<strong>定点</strong>。可表示集合仍是一个等差格子，动态范围仍约 \\(2^n\\)。科学计算要的是另一件事：相对精度大致均匀，绝对值可以从很小到很大。缺口因此不是再造一套补码，而是把一个数拆成<strong>尾数与指数</strong>，让格子在原点附近变密、在远处变疏。</p><p>本课只钉这两种读法的差别，不把位域写成 IEEE 754 的具体宽度。那是<a href="/cs/ieee-754">下一课</a>的缺口。</p><h3 id="浮点不是「实数」" tabindex="-1">浮点不是「实数」 <a class="header-anchor" href="#浮点不是「实数」" aria-label="Permalink to &quot;浮点不是「实数」&quot;">​</a></h3><p>定点是缩放整数，加减可以先对齐小数点再走整数 ALU。浮点的加减必须先对阶：指数不同则尾数要移位。结果通常不能精确表示，只能舍入。把浮点当成「连续量终于回来了」，会把<a href="/cs/bit-as-distinction">第一课</a>的判决丢掉：浮点仍然是有限比特串。</p><p><span class="marginnote">Goldberg 强调：浮点是有限集合上的算术，不是 \\(\\mathbb{R}\\) 的子集运算。Patterson/Hennessy 先讲定点缩放，再引入 \\(x = \\pm m\\times b^e\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定点：选定 \\(f\\)，数值为 \\(\\mathrm{val}(x)\\cdot 2^{-f}\\)（补码或无符号皆可）。乘法是整数乘再算术移位；溢出仍按整数规则，只是单位改了。</p><p>浮点：约定符号、尾数 \\(m\\)、指数 \\(e\\)，数值 \\(\\pm m\\times 2^e\\)（基 \\(2\\) 是后课默认）。规格化要求 \\(m\\) 落在半开区间 \\([1,2)\\)，使同一值只有一种写法——本课只要求这个直觉，隐藏位与偏置指数留给 IEEE 754。</p>',12)),(e(),l(E,null,{default:o(()=>[p(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20INT%5B%22%E8%A1%A5%E7%A0%81%E6%95%B4%E6%95%B0%22%5D%20--%3E%20FIX%5B%22%E5%AE%9A%E7%82%B9%EF%BC%9A%E9%92%89%E6%AD%BB%E5%B0%8F%E6%95%B0%E7%82%B9%22%5D%0A%20%20FIX%20--%3E%20FLT%5B%22%E6%B5%AE%E7%82%B9%EF%BC%9A%E6%8C%87%E6%95%B0%E7%A7%BB%E5%8A%A8%E5%B0%8F%E6%95%B0%E7%82%B9%22%5D%0A%20%20FLT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AIEEE%20754%20%E4%BD%8D%E5%9F%9F%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>定点把精度预算花在绝对误差上，适合货币的最小单位、传感器的固定刻度。浮点把预算花在有效位数上：加减会吞掉阶差过大的尾数，这是<strong>精度损失</strong>，不是补码那种溢出旗标。两种失败模式不要混名。</p><p>乘除对浮点相对自然：尾数乘、指数加。加减才是贵的。后课 ALU 会先做整数，浮点通路是另一套；本课只要求：同一比特串，读法从「整数」换成「定点或浮点」之后，相等关系都变了。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不规定 <code>binary32</code> 的 8 位指数、23 位尾数，不引入 NaN、无穷、非规格化数。也不讨论十进制浮点或区间算术。字符、文本编码与数值无关，是再后一课。</p><p>后课默认：谈到「机器上的非整数」，先问是定点缩放还是浮点。浮点的可移植位型，下一课才钉死。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>定点是缩放整数，格子均匀；浮点用指数换动态范围。</li><li>浮点加减要对阶并舍入；失败是精度损失，不是补码溢出。</li><li>规格化使同一值尽量一种写法；具体位域是后课。</li><li>出处：Patterson and Hennessy, COD (RISC-V)；Goldberg, 1991。</li></ul>',8))])}const g=n(h,[["render",c]]);export{b as __pageData,g as default};
